const sim = require('./sim.js');
const A = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } return a; } });
let r = sim(A, 42, 12020); console.log(r.score, r.fallTick, r.log.length, r.hash, JSON.stringify(r.log.slice(0,6)));
const B = () => ({ plan(s) { if (s.wave===1) return [{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}]; if (s.wave===3) return [{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}]; if (s.wave===6) return [{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]; return []; } });
r = sim(B, 7, 12020); console.log(r.score, r.fallTick, r.log.length, r.hash);
