function makeStrategy(CFG) {
  return function createStrategy() {
    var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
    var BASE = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
    var SPL = { cannon: 90, flak: 70 };
    var Q = CFG.queue, qi = 0;
    var P = CFG.p;
    var TW = { grunt: 1, runner: P.wRunner, wisp: P.wWisp, brute: P.wBrute, splitter: P.wSplitter, mender: P.wMender, splitling: P.wSplitling };
    var seq = 0, slowSeq = {};
    function dmgOf(type, tier) { var d = BASE[type]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
    function gpos(rem) { // ground position from remaining
      var p = 4600 - rem;
      if (p < 600) return [50 + p, 250];
      if (p < 1400) return [650, 250 + p - 600];
      if (p < 2000) return [650 + p - 1400, 1050];
      if (p < 2700) return [1250, 1050 - (p - 2000)];
      if (p < 3300) return [1250 + p - 2700, 350];
      if (p < 4100) return [1850, 350 + p - 3300];
      return [1850 + p - 4100, 1150];
    }
    function apos(rem) {
      var p = 2600 - rem;
      if (p < 2100) return [50 + p, 650];
      if (p < 2600 - 200) return [2150, 650 + p - 2100];
      return [2150 + p - 2400, 1150];
    }
    function val(c, d, pierce) {
      var e = pierce ? d : d - c.armor; if (e < 1) e = 1;
      var v = e >= c.hp ? c.hp * P.kill : e;
      v *= TW[c.type] || 1;
      if (c.remaining < P.urgDist) v *= P.urg;
      return v;
    }
    return {
      plan: function (s) {
        var acts = [], gold = s.gold, ts = [], i;
        for (i = 0; i < 16; i++) ts.push(s.slots[i].turret ? { type: s.slots[i].turret.type, tier: s.slots[i].turret.tier, spent: s.slots[i].turret.spent } : null);
        while (qi < Q.length && acts.length < 32) {
          var a = Q[qi], t = ts[a[1]];
          if (a[0] === 'b') {
            if (t) { qi++; continue; }
            if (gold < COST[a[2]]) break;
            gold -= COST[a[2]]; ts[a[1]] = { type: a[2], tier: 1, spent: COST[a[2]] };
            acts.push({ op: 'build', slot: a[1], type: a[2] });
          } else if (a[0] === 'u') {
            if (!t || t.tier >= 3) { qi++; continue; }
            var c = t.tier === 1 ? COST[t.type] : 2 * COST[t.type];
            if (gold < c) break;
            gold -= c; t.tier++; t.spent += c; acts.push({ op: 'upgrade', slot: a[1] });
          } else {
            if (!t) { qi++; continue; }
            gold += Math.floor(t.spent * 70 / 100); ts[a[1]] = null; acts.push({ op: 'sell', slot: a[1] });
          }
          qi++;
        }
        if (qi >= Q.length) {
          // fallback: upgrade anything affordable, most expensive first
          var go = true;
          while (go && acts.length < 32) {
            go = false; var bi = -1, bc = 0;
            for (i = 0; i < 16; i++) { t = ts[i]; if (!t || t.tier >= 3) continue; c = t.tier === 1 ? COST[t.type] : 2 * COST[t.type]; if (c <= gold && c > bc) { bc = c; bi = i; } }
            if (bi >= 0) { gold -= bc; ts[bi].tier++; acts.push({ op: 'upgrade', slot: bi }); go = true; }
          }
        }
        return acts;
      },
      target: function (t, cands) {
        var n = cands.length; if (n === 1) { if (t.type === 'frost') slowSeq[cands[0].id] = ++seq; return cands[0].id; }
        var type = t.type, d = dmgOf(type, t.tier), i, j, c, best = null, bv = -1, v;
        if (type === 'frost') {
          var br = 1e9;
          for (i = 0; i < n; i++) { c = cands[i]; if (c.slowed) continue;
            var r = c.remaining / (c.type === 'runner' ? P.frRunner : c.type === 'wisp' ? P.frWisp : 1);
            if (r < br) { br = r; best = c; } }
          if (!best) { var bs = 1e18; for (i = 0; i < n; i++) { c = cands[i]; var q = slowSeq[c.id] || 0; if (q < bs) { bs = q; best = c; } } }
          slowSeq[best.id] = ++seq; return best.id;
        }
        if (SPL[type]) {
          var s2 = SPL[type] * SPL[type], pos = [], vals = [];
          for (i = 0; i < n; i++) { c = cands[i]; pos.push(c.air ? apos(c.remaining) : gpos(c.remaining)); vals.push(val(c, d, false)); }
          for (i = 0; i < n; i++) {
            v = 0;
            for (j = 0; j < n; j++) { var dx = pos[i][0] - pos[j][0], dy = pos[i][1] - pos[j][1]; if (dx * dx + dy * dy <= s2) v += vals[j]; }
            if (v > bv || (v === bv && cands[i].remaining < best.remaining)) { bv = v; best = cands[i]; }
          }
          return best.id;
        }
        var pierce = type === 'lance';
        for (i = 0; i < n; i++) { c = cands[i]; v = val(c, d, pierce);
          if (v > bv || (v === bv && c.remaining < best.remaining)) { bv = v; best = c; } }
        return best.id;
      }
    };
  };
}

