load('sim.js'); load('strat.js');
var P0 = { wRunner: 1, wWisp: 1, wBrute: 1, wSplitter: 1, wMender: 2, wSplitling: 1, kill: 1.5, urgDist: 400, urg: 2, frRunner: 2, frWisp: 1.2 };
var SEEDS = []; for (var i = 1; i <= 20; i++) SEEDS.push(i * 101 + 7);
function evalCfg(cfg, seeds) { var tot = 0, out = []; seeds = seeds || SEEDS; for (var i = 0; i < seeds.length; i++) { var r = rampartSimulate(makeStrategy(cfg), seeds[i], 12020); tot += r.score; out.push(r.score); } return { mean: tot / seeds.length, all: out }; }
var Q1 = [['b',4,'bolt'],['b',3,'bolt'],['b',6,'bolt'],['b',5,'bolt'],['b',8,'bolt'],['b',1,'bolt'],['b',10,'cannon'],['b',7,'lance'],['u',4],['u',3],['u',6],['b',2,'frost'],['b',11,'lance'],['b',12,'cannon'],['b',9,'bolt'],['b',13,'bolt'],['b',14,'bolt'],['b',0,'bolt'],['b',15,'bolt']];
var t0 = Date.now();
var r = evalCfg({ queue: Q1, p: P0 }); print(r.mean.toFixed(2), r.all.join(' '), Date.now() - t0, 'ms');
var allBolt = []; for (i = 0; i < 16; i++) allBolt.push(['b', i, 'bolt']);
r = evalCfg({ queue: allBolt, p: P0 }); print(r.mean.toFixed(2), r.all.join(' '));

