load(arguments[0]);
var names = ['grunt','runner','wisp','brute','splitter','mender','splitling'];
function run(seed, verbose) {
  var types = {}, leaksBy = {}, lastTur = null, goldAt = [];
  rampartSimulate.recorder = {
    spawn: function (t, e) { types[e.id] = e.type; },
    kill: function (t, e, s, kids) { if (kids) kids.forEach(function (k) { types[k.id] = 6; }); },
    leak: function (t, e, hp) { var n = names[e.type]; leaksBy[n] = (leaksBy[n] || 0) + 1; if (verbose) print('  leak t=' + t + ' wave~' + ((t - 20) / 40 + 1).toFixed(1) + ' ' + n + ' w' + e.wave + ' hp->' + hp); },
    tick: function (t, en, tur, gold, hp, wave) { if ((t - 20) % 40 === 0) goldAt.push(gold); lastTur = tur; }
  };
  var r = rampartSimulate(makeStrategy(CFG), seed, 12020);
  rampartSimulate.recorder = null;
  if (verbose) {
    print('seed', seed, 'score', r.score, JSON.stringify(leaksBy));
    print('final turrets:', lastTur.map(function (t, i) { return t ? i + ':' + t.type + t.tier : i + ':-'; }).join(' '));
    print('gold by wave:', goldAt.join(','));
    print('actions:', r.log.filter(function (l) { return 'BUS'.indexOf(l[1]) >= 0; }).map(function (l) { return 'w' + ((l[0] - 20) / 40 + 1) + l[1] + l[2] + (l[1] === 'B' ? ['bolt','cannon','frost','lance','flak'][l[3]] : ''); }).join(' '));
  }
  return r.score;
}
