// composition search under unlimited gold: which final 16-turret layout holds longest?
var src = read('sim.js').replace('var gold = 250,', 'var gold = 1000000,');
eval(src.replace('function rampartSimulate', 'rampartSimulate = function'));
var rampartSimulate;
load('strat.js'); load(arguments[0]);
if (CFG.p.killB === undefined) { CFG.p.killB = 0.01; CFG.p.foc = 0.01; CFG.p.prog = 0.01; }
var RS = +arguments[1] || 1, ITERS = +arguments[2] || 300;
var rs = RS * 7919 + 13;
function rnd() { rs = (rs + 0x6D2B79F5) | 0; var t = Math.imul(rs ^ (rs >>> 15), 1 | rs); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function ri(n) { return Math.floor(rnd() * n); }
var TYPES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
var SEEDS = []; for (var i = 0; i < 12; i++) SEEDS.push(3000 + i * 53);
function evalComp(comp) {
  var q = []; for (var i = 0; i < 16; i++) { q.push(['b', i, comp[i]]); q.push(['u', i]); q.push(['u', i]); }
  var cfg = { queue: q, p: CFG.p }, tot = 0;
  for (i = 0; i < SEEDS.length; i++) tot += rampartSimulate(makeStrategy(cfg), SEEDS[i], 12020).score;
  return tot / SEEDS.length;
}
var cur = ['flak','flak','flak','bolt','bolt','cannon','cannon','cannon','cannon','cannon','cannon','cannon','cannon','cannon','bolt','frost'];
var curS = evalComp(cur); print('start', curS.toFixed(3), cur.join(','));
print('all cannon', evalComp(cur.map(function () { return 'cannon'; })).toFixed(3));
for (var it = 0; it < ITERS; it++) {
  var c = cur.slice(); c[ri(16)] = TYPES[ri(5)]; if (rnd() < 0.3) c[ri(16)] = TYPES[ri(5)];
  if (c.join() === cur.join()) continue;
  var s = evalComp(c);
  if (s >= curS) { if (s > curS) print(it, s.toFixed(3), c.join(',')); cur = c; curS = s; }
}
print('FINAL', curS.toFixed(3), JSON.stringify(cur));

